package gui;
import java.awt.*;import java.awt.event.*;import javax.swing.*;import javax.swing.table.DefaultTableModel;import datos.DatosSistema;import entidad.*;
public class FormCita extends JInternalFrame{
 private JComboBox<Paciente> cboPaciente;private JComboBox<Medico> cboMedico;private JTextField txtFecha,txtHora,txtBuscar;private DefaultTableModel model;
 public FormCita(){setTitle("Proceso: Registrar y Buscar Cita Médica");setClosable(true);setMaximizable(true);setIconifiable(true);setBounds(70,40,620,450);getContentPane().setLayout(new BorderLayout(5,5));JPanel f=new JPanel(new GridLayout(5,2,5,5));f.setBorder(BorderFactory.createTitledBorder("Agendar Cita"));f.add(new JLabel(" Paciente:"));cboPaciente=new JComboBox<>();f.add(cboPaciente);f.add(new JLabel(" Médico:"));cboMedico=new JComboBox<>();f.add(cboMedico);f.add(new JLabel(" Fecha (AAAA-MM-DD):"));txtFecha=new JTextField("2026-10-01");f.add(txtFecha);f.add(new JLabel(" Hora:"));txtHora=new JTextField("09:00 AM");f.add(txtHora);JButton b=new JButton("Agendar Cita");b.addActionListener(e->agendar());f.add(b);JPanel s=new JPanel(new BorderLayout());s.setBorder(BorderFactory.createTitledBorder("Buscar Cita por Paciente o Médico"));txtBuscar=new JTextField();txtBuscar.addKeyListener(new KeyAdapter(){public void keyReleased(KeyEvent e){actualizarCitas(txtBuscar.getText().trim());}});s.add(txtBuscar);JPanel n=new JPanel(new BorderLayout());n.add(f,BorderLayout.CENTER);n.add(s,BorderLayout.SOUTH);getContentPane().add(n,BorderLayout.NORTH);model=new DefaultTableModel(new Object[]{"ID","Fecha","Hora","Paciente","Médico","Estado"},0);getContentPane().add(new JScrollPane(new JTable(model)),BorderLayout.CENTER);}
 public void actualizarCitas(String filtro){cboPaciente.removeAllItems();for(Paciente p:DatosSistema.pacientes)cboPaciente.addItem(p);cboMedico.removeAllItems();for(Medico m:DatosSistema.medicos)cboMedico.addItem(m);model.setRowCount(0);for(Cita c:DatosSistema.citas){String p=c.getPaciente().getNombre(),m=c.getMedico().getNombre();if(p.toLowerCase().contains(filtro.toLowerCase())||m.toLowerCase().contains(filtro.toLowerCase()))model.addRow(new Object[]{c.getId(),c.getFecha(),c.getHora(),p,m,c.getEstado()});}}
 private void agendar(){if(cboPaciente.getSelectedItem()!=null&&cboMedico.getSelectedItem()!=null){String id="C"+String.format("%03d",DatosSistema.citas.size()+1);DatosSistema.citas.add(new Cita(id,txtFecha.getText().trim(),txtHora.getText().trim(),(Paciente)cboPaciente.getSelectedItem(),(Medico)cboMedico.getSelectedItem(),"Confirmada"));actualizarCitas("");FrmPrincipal.actualizarContadores();JOptionPane.showMessageDialog(this,"Cita agendada exitosamente.");}else JOptionPane.showMessageDialog(this,"Seleccione paciente y médico.");}
}
